44	// Lookup-table based 3-input logical operation; explicitly used for dequantization as the compiler does not seem to
45	// automatically recognize it in all cases. 
46	template <int lut>
47	__device__ inline int lop3(int a, int b, int c) {
48	  int res;
49	  asm volatile(
50	    "lop3.b32 %0, %1, %2, %3, %4;\n"
51	    : "=r"(res) : "r"(a), "r"(b), "r"(c), "n"(lut)
52	  );
53	  return res;
54	}
