174	template <typename Tensor0, typename Tensor1, typename Tensor2>
175	__forceinline__ __device__  
176	void 
177	load_params_Kchannel(
178	    Tensor0 & scales,
179	    Tensor1 & zeros,
180	    Tensor2 const& params,
181	    int tidx,
182	    int i,
183	    const int num_params
184	) {
185	    CUTE_UNROLL
186	    for (int m = 0; m < size<1>(scales); ++m) {
187	        CUTE_UNROLL
188	        for (int j = 0; j < size<0>(scales); ++j) {
189	            // seems no one can know why is this offset ... 
190	            scales(j, m, i) = params(m * num_params + j % num_params, 0  + 8 * i + 4 * (j / num_params) + tidx % 4);
191	            zeros(j, m, i)  = params(m * num_params + j % num_params, 64 + 8 * i + 4 * (j / num_params) + tidx % 4);
192	        }
193	    }
194	}
